// The seeded tag library, read from the bundled library.json — the same bytes
// packages/core/contract ships, generated by scripts/gen-vault-contract.mts. The library
// stays in the app; a tag copies INTO the vault's registry the first time a row wears it,
// so the file alone always explains every tag it uses.
import Foundation

public enum TagLibrary {
    public struct Entry {
        public let kind: String
        public let name: String
        public let nameKey: String
        public let icon: String?
        public let sort: Int
    }

    /// Every seeded tag, in library order. Loaded once; the bundle never changes mid-run.
    public static let all: [Entry] = {
        guard let url = Bundle.module.url(forResource: "library", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let rows = root["tags"] as? [[String: Any]]
        else { return [] }
        return rows.compactMap { row in
            guard let kind = row["kind"] as? String, let name = row["name"] as? String else { return nil }
            return Entry(
                kind: kind,
                name: name,
                nameKey: row["name_key"] as? String ?? nameKey(name),
                icon: row["icon"] as? String,
                sort: row["sort"] as? Int ?? 0
            )
        }
    }()

    public static func entries(kind: String) -> [Entry] {
        all.filter { $0.kind == kind }
    }

    public static func entry(kind: String, name: String) -> Entry? {
        let key = nameKey(name)
        return all.first { $0.kind == kind && $0.nameKey == key }
    }
}
